CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE institutions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,region text NOT NULL DEFAULT '',active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE institution_memberships(user_id uuid NOT NULL,institution_id uuid NOT NULL REFERENCES institutions(id),role text NOT NULL CHECK(role IN ('staff','institution_admin')),active boolean NOT NULL DEFAULT true,PRIMARY KEY(user_id,institution_id));
CREATE TABLE platform_admins(user_id uuid PRIMARY KEY,active boolean NOT NULL DEFAULT true);
CREATE TABLE items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),institution_id uuid NOT NULL REFERENCES institutions(id),reporter_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN ('lost','found')),category text NOT NULL DEFAULT '',private_title text NOT NULL,private_description text NOT NULL DEFAULT '',private_location text NOT NULL DEFAULT '',public_title text NOT NULL DEFAULT '',public_description text NOT NULL DEFAULT '',public_location text NOT NULL DEFAULT '',contact_details text NOT NULL DEFAULT '',occurred_on date,status text NOT NULL DEFAULT 'open',review_status text NOT NULL DEFAULT 'pending' CHECK(review_status IN ('pending','approved','rejected')),visibility text NOT NULL DEFAULT 'private' CHECK(visibility IN ('private','public')),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX items_public_idx ON items(created_at DESC) WHERE review_status='approved' AND visibility='public';
CREATE TABLE cases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),item_id uuid NOT NULL UNIQUE REFERENCES items(id),institution_id uuid NOT NULL REFERENCES institutions(id),status text NOT NULL DEFAULT 'open',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE claims(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),item_id uuid NOT NULL REFERENCES items(id),claimant_id uuid NOT NULL,statement text NOT NULL,contact_details text NOT NULL DEFAULT '',evidence_reference text NOT NULL DEFAULT '',staff_note text NOT NULL DEFAULT '',status text NOT NULL DEFAULT 'pending',reviewed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE handovers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),case_id uuid NOT NULL REFERENCES cases(id),institution_id uuid NOT NULL REFERENCES institutions(id),handover_at timestamptz NOT NULL,details text NOT NULL DEFAULT '',recipient text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
